33	/**
34	 * Programmatic "(location) (service)" marketing landing pages, the region-tier
35	 * umbrella pages above them, AND (added here) the game-family × location
36	 * matrix + the general per-location VPS/Game-Server pages that don't already
37	 * exist via the tables above — see lib/marketing/gameLocationLandings.ts's
38	 * file doc for the full architecture note.
39	 *
40	 * Four data tables, one route: a slug is checked against the region matrix,
41	 * then the city matrix, then the game×location matrix, then the general
42	 * new-location matrix — in that order, so nothing here can ever shadow a
43	 * hand-written static marketing page (which wins at request time anyway) or
44	 * silently collide with an existing slug. Anything in none of the four falls
45	 * through to a 404. Real DB rows (VPS `Plan` or, for a game×location combo,
46	 * that family's real `GamePlan` rows) feed every page's pricing grid and
47	 * Product rich-result — nothing here is a hardcoded price.
48	 */
49	
50	export const dynamic = "force-dynamic";
51	
52	// Pre-declare every known slug across all four tables so Next can enumerate
53	// them at build time; unknown slugs are rejected in the page/metadata via
54	// notFound().
55	export function generateStaticParams(): Array<{ slug: string }> {
56	  return [...REGION_LANDING_SLUGS, ...LANDING_SLUGS, ...GAME_LOCATION_SLUGS, ...GENERAL_LOCATION_SLUGS].map((slug) => ({
57	    slug,
58	  }));
59	}
60	
61	async function loadVpsPlans(): Promise<LandingPlan[]> {
62	  return db.plan.findMany({
63	    where: { active: true },
64	    orderBy: { sortOrder: "asc" },
65	  });
66	}
67	
68	/**
69	 * Real, active `GamePlan` rows for one family, mapped both to the plain
70	 * `GamePlanRow[]` the copy builder reads for prose (RAM/slots/price only)
71	 * and to full `PlanCard[]` for the pricing grid — `bandwidthTB`/`storageTier`
72	 * come from each row's real `basePlan` (the actual VPS-grade Plan the game
73	 * server is provisioned on), never a fabricated number.
74	 */
75	async function loadGamePlans(gameFamily: string): Promise<{ rows: GamePlanRow[]; cards: PlanCard[] }> {
76	  const plans = await db.gamePlan.findMany({
77	    where: { gameFamily, active: true },
78	    orderBy: { sortOrder: "asc" },
79	    include: { basePlan: true },
80	  });
81	  const rows: GamePlanRow[] = plans.map((p) => ({
82	    id: p.id,
83	    name: p.name,
84	    ramMB: p.ramMB,
85	    slots: p.slots,
86	    priceCents: p.priceCents,
87	    introPriceCents: p.introPriceCents,
88	  }));
89	  const cards: PlanCard[] = plans.map((p) => ({
90	    id: p.id,
91	    name: p.name,
92	    cpuCores: p.cpuCores,
93	    ramMB: p.ramMB,
94	    diskGB: p.diskGB,
95	    bandwidthTB: p.basePlan.bandwidthTB,
96	    priceCents: p.priceCents,
97	    storageTier: p.basePlan.storageTier,
98	    introMonthlyCents: p.introPriceCents,
99	    slots: p.slots,
100	  }));
101	  return { rows, cards };
102	}
103	
104	/**
105	 * Discriminant is NOT "does this page's service key happen to be `game`" —
106	 * the pre-existing city/region/general-location "game server hosting" pages
107	 * (e.g. "toronto-game-server-hosting") already price themselves off generic
108	 * VPS `Plan` rows (same as every other service on those tables) and deploy
109	 * as `service=vps`, unchanged from before this file existed. Only a genuine
110	 * per-family combo (e.g. "singapore-minecraft-server-hosting", resolved via
111	 * `findGameLocationCombo`) prices off that family's real `GamePlan` rows and
112	 * needs `service="game"` + `gameFamily` wired through to the deploy links.
113	 */
114	type Resolved =
115	  | { kind: "generic"; built: BuiltLanding; plans: LandingPlan[] }
116	  | {
117	      kind: "game-family";
118	      built: BuiltLanding;
119	      plans: PlanCard[];
120	      gameFamily: string;
121	      productName: string;
122	      /**
123	       * The GameLandingCombined-ready merge (real pricing + this combo's
124	       * honesty framing over the game's PREVIEW_GAMES fixture) — see
125	       * lib/marketing/gameLocationLandings.ts's buildGameLocationPreviewGame
126	       * doc. `undefined` only if `family` somehow has no PREVIEW_GAMES entry
127	       * (shouldn't happen for anything in ACTIVE_GAME_FAMILIES), in which case
128	       * the page below falls back to the generic UseCaseLanding render so a
129	       * drift between the two lists degrades gracefully instead of 500ing.
130	       */
131	      previewGame: PreviewGame | undefined;
132	    };
133	
134	async function resolve(slug: string): Promise<Resolved | undefined> {
135	  const regionCombo = findRegionCombo(slug);
136	  if (regionCombo) {
137	    const plans = await loadVpsPlans();
138	    return { kind: "generic", built: buildRegionLanding(regionCombo, plans), plans };
139	  }
140	
141	  const combo = findCombo(slug);
142	  if (combo) {
143	    const plans = await loadVpsPlans();
144	    return { kind: "generic", built: buildLanding(combo, plans), plans };
145	  }
146	
147	  const generalCombo = findGeneralLocationCombo(slug);
148	  if (generalCombo) {
149	    const plans = await loadVpsPlans();
150	    return { kind: "generic", built: buildGeneralLocationLanding(generalCombo, plans), plans };
151	  }
152	
153	  const gameCombo = findGameLocationCombo(slug);
154	  if (gameCombo) {
155	    const { rows, cards } = await loadGamePlans(gameCombo.family);
156	    const built = buildGameLocationLanding(gameCombo, rows);
157	    const previewGame = buildGameLocationPreviewGame(gameCombo, cards);
158	    return { kind: "game-family", built, plans: cards, gameFamily: built.gameFamily, productName: built.productName, previewGame };
159	  }
160	
161	  return undefined;
162	}
