164	export async function generateMetadata({
165	  params,
166	}: {
167	  params: Promise<{ slug: string }>;
168	}): Promise<Metadata> {
169	  const { slug } = await params;
170	  const resolved = await resolve(slug);
171	  if (!resolved) return {};
172	  const { built } = resolved;
173	
174	  const url = `${APP_URL}/${slug}`;
175	
176	  return {
177	    title: built.metaTitle,
178	    description: built.metaDescription,
179	    alternates: { canonical: `/${slug}` },
180	    openGraph: {
181	      type: "article",
182	      title: built.ogTitle,
183	      description: built.ogDescription,
184	      url,
185	    },
186	    twitter: {
187	      card: "summary_large_image",
188	      title: built.ogTitle,
189	      description: built.ogDescription,
190	    },
191	  };
192	}
