194	export default async function LocationServiceLandingPage({
195	  params,
196	}: {
197	  params: Promise<{ slug: string }>;
198	}) {
199	  const { slug } = await params;
200	  const resolved = await resolve(slug);
201	  if (!resolved) notFound();
202	  const { built, plans } = resolved;
203	
204	  const url = `${APP_URL}/${slug}`;
205	
206	  // BreadcrumbList — helps Google render the Home › <Page> trail and reinforces
207	  // the page's place in the site. FAQ + Product JSON-LD are emitted below,
208	  // either by UseCaseLanding (generic pages) or directly here (game-family
209	  // combos rendered through GameLandingCombined instead), so all three rich
210	  // results are covered either way.
211	  const breadcrumb = {
212	    "@context": "https://schema.org",
213	    "@type": "BreadcrumbList",
214	    itemListElement: [
215	      { "@type": "ListItem", position: 1, name: "Home", item: APP_URL },
216	      { "@type": "ListItem", position: 2, name: built.breadcrumbName, item: url },
217	    ],
218	  };
219	
220	  // Game×location combos render through the SAME flagship template as the
221	  // ~40 hand-built per-game pages (GameLandingCombined) instead of the
222	  // generic UseCaseLanding/PricingGrid path — see gameLocationLandings.ts's
223	  // buildGameLocationPreviewGame. Falls through to the generic branch below
224	  // if `family` somehow has no PREVIEW_GAMES fixture (shouldn't happen).
225	  if (resolved.kind === "game-family" && resolved.previewGame) {
226	    const { built: gameBuilt, previewGame, productName } = resolved;
227	    return (
228	      <>
229	        <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }} />
230	        <FaqJsonLd items={gameBuilt.content.faq} />
231	        <ProductOffersJsonLd
232	          name={productName}
233	          description={gameBuilt.content.sub}
234	          url={url}
235	          offers={resolved.plans.map((p) => ({ name: p.name, price: p.priceCents / 100 }))}
236	        />
237	
238	        <GameLandingCombined game={previewGame} reviewBadges={<ReviewBadges />} />
239	
240	        {/* FAQ + related — carried over from the same content the ~40 static
241	         * per-game pages ship below GameLandingCombined (e.g. rust-server-
242	         * hosting/page.tsx), reusing this combo's own honest, location-aware
243	         * copy from buildGameLocationLanding rather than duplicating it. */}
244	        <Section tone="base" size="md">
245	          <SectionTitle eyebrow="FAQ" title="Questions, answered" />
246	          <div className="mx-auto mt-10 max-w-3xl space-y-3">
247	            {gameBuilt.content.faq.map((f) => (
248	              <details key={f.q} className="card group">
249	                <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
250	                  <span className="flex items-center justify-between gap-4">
251	                    {f.q}
252	                    <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
253	                  </span>
254	                </summary>
255	                <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
256	              </details>
257	            ))}
258	          </div>
259	        </Section>
260	
261	        {gameBuilt.content.related && gameBuilt.content.related.length > 0 && (
262	          <Section tone="base" size="sm">
263	            <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
264	              <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
265	              {gameBuilt.content.related.map((r) => (
266	                <Link
267	                  key={r.href}
268	                  href={r.href}
269	                  className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
270	                >
271	                  {r.label}
272	                </Link>
273	              ))}
274	            </div>
275	          </Section>
276	        )}
277	      </>
278	    );
279	  }
280	
281	  return (
282	    <>
283	      <script
284	        type="application/ld+json"
285	        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }}
286	      />
287	      <UseCaseLanding
288	        content={built.content}
289	        plans={plans as PlanCard[]}
290	        service={resolved.kind === "game-family" ? "game" : "vps"}
291	        gameFamily={resolved.kind === "game-family" ? resolved.gameFamily : undefined}
292	        productName={resolved.kind === "game-family" ? resolved.productName : undefined}
293	        pageUrl={url}
294	      />
295	    </>
296	  );
297	}
