11	 *
12	 * Social proof is split into two clearly-distinct things (2026-08-29 revision):
13	 *   - The real aggregate rating/count is <ReviewBadges/> (Google/Trustpilot/
14	 *     HostAdvice), rendered by the route page and passed in as a prop. That is
15	 *     the only place a star average or review count is ever shown.
16	 *   - `reviews` below are ILLUSTRATIVE example feedback, not real customer
17	 *     submissions — no invented personal names and no per-quote star rating
18	 *     (that would imply a specific measured score). Attribution is a generic
19	 *     `role` string (e.g. "Rust wipe admin") and every render of this data is
20	 *     required to visibly label it as illustrative/example content.
21	 */
22	
23	export type PreviewPlan = {
24	  id: string;
25	  /** Short tier label, e.g. "Wipe" / "Community". */
26	  tier: string;
27	  /** RAM headline, e.g. "6 GB". */
28	  ram: string;
29	  /** Displayed price, e.g. "$17.99". Rendered with a trailing "/mo". */
30	  price: string;
31	  /** Right-aligned spec meta, e.g. "60 slots" or "4 vCPU · 120 GB NVMe". */
32	  meta: string;
33	  /**
34	   * Advertised player-slot capacity for this plan, when it has one. Drives the
35	   * interactive pricing configurator's player-count → plan matching. Omitted for
36	   * VPS-style plans (e.g. Satisfactory) that are sized by RAM rather than slots —
37	   * those fall back to the fitted RAM curve in lib/game-player-recommend.
38	   */
39	  slots?: number;
40	  blurb: string;
41	  popular?: boolean;
42	  features: string[];
43	  /**
44	   * Regular/renewal MONTHLY price (e.g. "$17.99"), set ONLY when `price` above is
45	   * a discounted first-term intro rate. Added 2026-09-19 for the game×location
46	   * matrix (lib/marketing/gameLocationLandings.ts's adapter), which prices plans
47	   * from live `GamePlan.priceCents`/`introPriceCents` and must disclose the
48	   * renewal the same way PricingGrid.tsx already does — optional so every
49	   * existing PREVIEW_GAMES entry below (flat `price`, no intro/renewal split)
50	   * renders exactly as before.
51	   */
52	  renewalPrice?: string;
53	};
