/**
 * TEMPORARY diagnostic script — deleted after use.
 *
 * Systematically checks every real game family (lib/games.ts GAME_FAMILIES)
 * against:
 *   1. The canonical marketing slug this codebase already defines
 *      (lib/marketing/gameLocationLandings.ts's GAME_URL_SLUG map) +
 *      "-server-hosting".
 *   2. Whether a real app/(marketing)/<slug>/page.tsx folder exists for that
 *      canonical slug.
 *   3. The REAL production HTTP status for that canonical URL.
 *   4. The REAL production HTTP status for the "naive" URL built directly
 *      from the raw family key (`${family}-server-hosting`) — this is what
 *      app/(marketing)/mods/[family]/[slug]/page.tsx and
 *      app/(marketing)/mods/games/[family]/page.tsx actually generate today,
 *      which is the suspected bug.
 *   5. Whether that family has a PREVIEW_GAMES entry (gates whether the
 *      mods/games/[family] page ever renders the buggy "See ... hosting
 *      plans" link at all).
 */
import { GAME_FAMILIES, type GameFamily } from "../lib/games";
import { GAME_URL_SLUG } from "../lib/marketing/gameLocationLandings";
import { PREVIEW_GAMES } from "../components/marketing/gamelanding/data";
import fs from "node:fs";
import path from "node:path";

const APP_URL = "https://nxeon.cloud";
const MARKETING_DIR = path.join(__dirname, "..", "app", "(marketing)");

async function statusFor(pathname: string): Promise<number | string> {
  try {
    const res = await fetch(`${APP_URL}/${pathname}`, { method: "GET", redirect: "manual" });
    return res.status;
  } catch (e) {
    return `ERR:${e instanceof Error ? e.message : String(e)}`;
  }
}

function folderExists(slug: string): boolean {
  return fs.existsSync(path.join(MARKETING_DIR, slug, "page.tsx"));
}

async function main() {
  console.log(`Total GAME_FAMILIES: ${GAME_FAMILIES.length}`);
  console.log(
    "family".padEnd(18),
    "canonicalSlug".padEnd(28),
    "canonicalFolder".padEnd(16),
    "canonicalHTTP".padEnd(14),
    "naiveSlug".padEnd(28),
    "naiveHTTP".padEnd(10),
    "hasPreviewGame"
  );

  const rows: {
    family: GameFamily;
    canonicalSlug: string;
    canonicalFolder: boolean;
    canonicalHTTP: number | string;
    naiveSlug: string;
    naiveHTTP: number | string;
    hasPreviewGame: boolean;
    mismatch: boolean;
  }[] = [];

  for (const family of GAME_FAMILIES) {
    const urlSlugPart = GAME_URL_SLUG[family];
    const canonicalSlug = `${urlSlugPart}-server-hosting`;
    const naiveSlug = `${family}-server-hosting`;
    const canonicalFolder = folderExists(canonicalSlug);
    const canonicalHTTP = await statusFor(canonicalSlug);
    const naiveHTTP = naiveSlug === canonicalSlug ? canonicalHTTP : await statusFor(naiveSlug);
    const hasPreviewGame = family in PREVIEW_GAMES;
    const mismatch = urlSlugPart !== family;
    rows.push({ family, canonicalSlug, canonicalFolder, canonicalHTTP, naiveSlug, naiveHTTP, hasPreviewGame, mismatch });
    console.log(
      family.padEnd(18),
      canonicalSlug.padEnd(28),
      String(canonicalFolder).padEnd(16),
      String(canonicalHTTP).padEnd(14),
      naiveSlug.padEnd(28),
      String(naiveHTTP).padEnd(10),
      String(hasPreviewGame)
    );
  }

  console.log("\n=== SUMMARY ===");
  const canonical404 = rows.filter((r) => r.canonicalHTTP !== 200);
  console.log(`\nFamilies whose CANONICAL (${"{slug}"}-server-hosting) URL does NOT return 200:`);
  for (const r of canonical404) {
    console.log(`  ${r.family} -> /${r.canonicalSlug} => ${r.canonicalHTTP} (folder exists: ${r.canonicalFolder})`);
  }

  const naiveBroken = rows.filter((r) => r.mismatch && r.naiveHTTP !== 200);
  console.log(`\nFamilies where the NAIVE slug (raw family key, what the mods pages generate) 404s:`);
  for (const r of naiveBroken) {
    console.log(
      `  ${r.family} -> /${r.naiveSlug} => ${r.naiveHTTP}  (real page is /${r.canonicalSlug} => ${r.canonicalHTTP}, hasPreviewGame=${r.hasPreviewGame})`
    );
  }

  console.log(`\nTotal families: ${rows.length}`);
  console.log(`Canonical 404s (real content gaps): ${canonical404.length}`);
  console.log(`Naive-slug breaks (slug-mismatch bug): ${naiveBroken.length}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

